const raw=$input.first().json||{};
const b=raw.body&&typeof raw.body==='object'?raw.body:raw;
const entrypoint=['production','test'].includes(raw.formMode)?'form':(raw.body?'webhook':'manual');
const name=String(b.company_name||'').trim();
const register=String(b.register_identifier||'').trim();
if(name.length<2||name.length>200) return [{json:{valid:false,entrypoint,error_code:'invalid_company_name',message:'company_name must contain 2–200 characters.'}}];
if(register.length>100||/[\r\n\0]/.test(register)) return [{json:{valid:false,entrypoint,error_code:'invalid_register_identifier',message:'register_identifier is invalid.'}}];
return [{json:{valid:true,entrypoint,company_name:name,register_identifier:register||null,requested_at:new Date().toISOString()}}];

const raw=$input.first().json.body||$input.first().json;
const rows=Array.isArray(raw.results)?raw.results:[];
const req=$('Normalize Input').first().json;
const norm=s=>String(s||'').normalize('NFKC').toLocaleLowerCase('de').replace(/[^\p{L}\p{N}]/gu,'');
const normEntity=s=>norm(s).replace(/aktiengesellschaft$/,'ag');
const regNorm=s=>String(s||'').replace(/[^\p{L}\p{N}]/gu,'').toLocaleLowerCase('de');
const candidates=req.register_identifier
 ? rows.filter(r=>[r.register_number,r.company_id,`${r.register_type||''}${r.register_number||''}`].some(x=>regNorm(x)===regNorm(req.register_identifier)))
 : rows.filter(r=>normEntity(r.name)===normEntity(req.company_name));
const tokenSet=s=>new Set((String(s||'').normalize('NFKC').toLocaleLowerCase('de').match(/[\p{L}\p{N}]{2,}/gu)||[]).filter(t=>!['gmbh','ag','se','kg','ug','mbh','aktiengesellschaft','gesellschaft','mit','beschrankter','haftung'].includes(t)));
const requestedTokens=tokenSet(req.company_name);
const plausible=rows.filter(r=>{
 const nameTokens=tokenSet(r.name);
 return requestedTokens.size>0&&[...requestedTokens].every(t=>[...nameTokens].some(n=>n===t||n.startsWith(t)||t.startsWith(n)));
});
const displayCandidates=candidates.length>1?candidates:(candidates.length===0?plausible:[]);
const safeCandidates=displayCandidates.filter(r=>/^[A-Za-z0-9-]{5,100}$/.test(String(r.company_id||''))&&typeof r.name==='string'&&r.name.trim());
const list=safeCandidates.slice(0,10).map((r,i)=>{
 const number=String(r.register_number||r.register?.register_number||'not provided');
 const court=String(r.register_court||r.register?.register_court||'not provided');
 return `${i+1}. ${r.name} — ${r.register_type||r.register?.register_type||'Register'} ${number} — ${court}`;
});
if(candidates.length!==1) return [{json:{valid:false,failed_step:'OpenRegister identity resolution',error_code:candidates.length?'ambiguous_registry_identity':(safeCandidates.length?'company_candidate_selection_required':'exact_company_match_not_found'),candidate_count:safeCandidates.length,candidates:list,message:safeCandidates.length?`No company was selected automatically. Plausible OpenRegister candidates:\n${list.join('\n')}\nRestart research using the exact registered company name. If names are duplicated, enter the register number in the optional register-number field.`:(candidates.length?'Registry identity is ambiguous, but OpenRegister did not return safely displayable candidate details. Enter a register number.':'No exact or plausible OpenRegister company match was found. Check the company name and try again.')}}];
const c=candidates[0];
if(!/^[A-Za-z0-9-]{5,100}$/.test(String(c.company_id||''))) return [{json:{valid:false,failed_step:'OpenRegister identity resolution',error_code:'invalid_registry_identifier',message:'OpenRegister returned no valid company identifier.'}}];
return [{json:{...req,valid:true,registry_match:c}}];

const d=$input.first().json.body||$input.first().json;
const name=d.name?.name||d.name||$('Select Exact Entity').first().json.registry_match.name;
if(typeof name!=='string'||!name.trim()) throw new Error('OpenRegister company name missing');
const match=$('Select Exact Entity').first().json.registry_match;
const company={name,company_id:d.id||match.company_id,
 legal_form:d.legal_form||d.name?.legal_form||match.legal_form||null,register:d.register||d.company_register||match.register||{register_court:match.register_court||null,register_number:match.register_number||null,register_type:match.register_type||null},address:d.address||match.address||null,
 purpose:d.purpose?.purpose||d.purpose||null,industry_codes:d.industry_codes||null,status:d.status||null,
 retrieved_at:new Date().toISOString(),register_source:'OpenRegister API'};
const address=typeof company.address==='string'?company.address:JSON.stringify(company.address||{});
const purpose=typeof company.purpose==='string'?company.purpose:JSON.stringify(company.purpose||{});
const location=String((company.register||{}).register_court||'')+' '+address;
const search_query='"'+name+'" '+location+' '+purpose+' official website products services recent news developments';
return [{json:{company,company_name:name,search_query}}];

const cards=[{"id": "RAG-METHOD-01", "title": "Corporate identity verification", "text": "Match the exact registered entity using its legal name and register identifier. Distinguish registry-derived fields from third-party reports. A registry match does not establish current status unless the source provides a retrieval timestamp."}, {"id": "RAG-SOURCE-02", "title": "Source reliability", "text": "Prefer official company and registry sources for identity and registered details. Label search snippets as unverified leads. Record source URL, retrieval timestamp, and any publication date. Do not convert absence of a search result into evidence that an event did not occur."}, {"id": "RAG-DILIGENCE-03", "title": "Meeting preparation checklist", "text": "Confirm corporate identity, business model, products and services, material public developments, management context, and information gaps. Separate verified source facts from interpretation. Frame follow-up questions as questions, not allegations."}, {"id": "RAG-LIMIT-04", "title": "Scope limitations", "text": "Public-source company research is not a legal opinion, conflict check, solvency conclusion, sanctions screening, or verification of management authority. State coverage and evidence limitations explicitly."}];
const q=$('Prepare Tavily Query').first().json;
const terms=new Set((String(q.company.purpose||'')+' '+String(q.company.legal_form||'')+' corporate diligence sources follow-up').toLocaleLowerCase().match(/[\p{L}\p{N}]{4,}/gu)||[]);
const selected=cards.map(c=>({c,score:(c.title+' '+c.text).toLocaleLowerCase().match(/[\p{L}\p{N}]{4,}/gu)?.filter(t=>terms.has(t)).length||0})).sort((a,b)=>b.score-a.score).slice(0,3).map(x=>x.c);
return [{json:{company:q.company,search_query:q.search_query,rag_context:selected}}];

/* Dependency-free Tavily result filter for n8n's restricted Code-node VM. */
function parseTavilySources(results, company, retrievedAt) {
  const rejected = {};
  const reject = (reason) => { rejected[reason] = (rejected[reason] || 0) + 1; };
  const normalize = (value) => String(value || '').normalize('NFKD').replace(/\p{Diacritic}/gu, '').toLowerCase();
  const tokens = (value) => normalize(value).match(/[\p{L}\p{N}]+/gu) || [];
  const stop = new Set(['gmbh','ag','se','ug','kg','ohg','kgaa','ev','the','and','und','company','co','group','holding','international','deutschland']);
  const brands = tokens(company?.name).filter((word) => word.length >= 3 && !stop.has(word));
  const purpose = typeof company?.purpose === 'string' ? company.purpose : JSON.stringify(company?.purpose || '');
  const activity = tokens(purpose).filter((word) => word.length >= 5 && !stop.has(word));
  const location = tokens(JSON.stringify([company?.register?.register_court, company?.address]))
    .filter((word) => word.length >= 4 && !/^\d+$/.test(word) && !stop.has(word) && !['strasse','street','road','avenue','berlincharlottenburg'].includes(word));
  const related = (needles, text) => {
    const words = new Set(tokens(text));
    return needles.some((needle) => [...words].some((word) => word === needle ||
      (Math.min(word.length, needle.length) >= 5 && (word.startsWith(needle) || needle.startsWith(word)))));
  };
  const decode = (value) => String(value || '').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"')
    .replace(/&#39;|&apos;/gi,"'").replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&nbsp;/gi,' ')
    .replace(/&#(?:x([0-9a-f]+)|(\d+));?/gi, (whole, hex, dec) => {
      const n = parseInt(hex || dec, hex ? 16 : 10);
      try { return Number.isFinite(n) ? String.fromCodePoint(n) : whole; } catch { return whole; }
    });
  const safeUrl = (value) => {
    const match = /^(https?):\/\/([^/?#]+)([^?#]*)(?:\?([^#]*))?(?:#.*)?$/i.exec(String(value || '').trim());
    if (!match || match[2].includes('@')) return null;
    const host = match[2].replace(/:\d+$/, '').toLowerCase().replace(/^www\./, '');
    if (!/^(?=.{1,253}$)[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,63}$/i.test(host) || /\.(local|internal)$/i.test(host)) return null;
    const keys = (match[4] || '').split('&').filter(Boolean).map((part) => {
      const key = part.split('=')[0].replace(/\+/g, ' ');
      try { return decodeURIComponent(key); } catch { return key; }
    });
    if (keys.some((key) => /token|signature|credential|secret|auth/i.test(key))) return null;
    return { raw: String(value).trim(), host, path: match[3] || '/' };
  };
  const sources = [], seen = new Set();
  const social = /(^|\.)(instagram|facebook|linkedin|tiktok|x|twitter|youtube)\.com$/;
  for (const row of Array.isArray(results) ? results : []) {
    const url = safeUrl(row?.url);
    if (!url) { reject('unsafe_or_invalid_url'); continue; }
    const title = decode(row?.title).replace(/[\r\n\t]+/g, ' ').trim().slice(0, 300);
    const content = decode(row?.content).replace(/\r\n?/g, '\n').trim().slice(0, 4000);
    if (!title || !content) { reject('missing_title_or_excerpt'); continue; }
    const brandedHost = url.host.split('.').some((part) => brands.includes(part));
    const brandMatch = brandedHost || related(brands, title + ' ' + content);
    if (!brandMatch) { reject('brand_mismatch'); continue; }
    const context = title + ' ' + content + ' ' + url.host;
    const activityMatch = activity.length > 0 && related(activity, context);
    const locationMatch = location.length > 0 && related(location, context);
    // A company-branded domain is a useful discovery lead even if a short snippet omits the registry's exact activity wording.
    if (!activityMatch && !locationMatch && !brandedHost) { reject('irrelevant_context'); continue; }
    const key = url.host + url.path.replace(/\/$/, '').toLowerCase();
    if (seen.has(key)) { reject('duplicate_url'); continue; }
    seen.add(key);
    const sourceType = social.test(url.host) ? 'social_media' : (brandedHost ? 'company_site_candidate' : 'public_web');
    const confidence = brandedHost && activityMatch && locationMatch ? 'medium' : 'low';
    const published = typeof row.published_date === 'string' && Number.isFinite(Date.parse(row.published_date)) ? row.published_date.slice(0, 40) : null;
    sources.push({
      id: 'WEB-' + (sources.length + 1), kind: 'web_lead', source_type: sourceType,
      title, url: url.raw, content, retrieved_at: retrievedAt, published_at: published,
      confidence,
      confidence_note: sourceType === 'company_site_candidate'
        ? 'Brand-domain signal; ownership by the registered legal entity was not independently verified.'
        : 'Unverified public web material; source identity and claims were not independently verified.',
      relevance_signals: [brandMatch ? 'company-name or brand-domain match' : null, activityMatch ? 'business-activity match' : null, locationMatch ? 'location match' : null].filter(Boolean),
      tavily_score: Number.isFinite(Number(row.score)) ? Number(row.score) : null,
    });
    if (sources.length >= 5) break;
  }
  return { sources, raw_result_count: Array.isArray(results) ? results.length : 0, rejected_reasons: rejected };
}

const c=$('Local RAG').first().json;
const envelope=$('Tavily Search').first().json;
const response=envelope.body||envelope;
if(!Array.isArray(response.results)) throw new Error('Tavily did not return a results list');
const web=parseTavilySources(response.results,c.company,new Date().toISOString());
const sources=[{id:'REGISTRY-1',kind:'registry',source_type:'official_registry',confidence:'official_registry_record',title:'OpenRegister company record',url:'https://api.openregister.de/v1/company/'+encodeURIComponent(c.company.company_id),retrieved_at:c.company.retrieved_at,published_at:null,content:JSON.stringify(c.company)},...web.sources];
return [{json:{company:c.company,rag_context:c.rag_context,sources,search_query:c.search_query,tavily_result_count:web.raw_result_count,tavily_http_status:envelope.statusCode||null,tavily_accepted_count:web.sources.length,tavily_rejected_reasons:web.rejected_reasons}}];

/* Stable Markdown rendering for the validated Project 3 report contract. */
function renderCorporateReport(report, evidence, run) {
  const clean = (value) => {
    const markdown = new Set(['\\','*','_','`','{','}','[',']','#','+','!','>','|']);
    return Array.from(String(value || '').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"')
      .replace(/&#39;|&apos;/gi,"'").replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&nbsp;/gi,' ')
      .replace(/[\r\n\t]+/g,' ').replace(/[<>]/g,'')).map((char)=>markdown.has(char)?'\\'+char:char).join('');
  };
  const bullet = (text, ids=[]) => '- '+clean(text)+(ids.length?' ['+ids.join(', ')+']':'');
  const citedClaim = (claim) => bullet(claim.text+(claim.claim_type==='analysis'?' (analytical inference)':''),claim.source_ids);
  const c = evidence.company, reg = c.register || {};
  const profile = [
    '- Legal name: '+clean(c.name)+' [REGISTRY-1]',
    '- Legal form: '+clean(c.legal_form||'Not returned')+' [REGISTRY-1]',
    '- Register identifier: '+clean([reg.register_type,reg.register_number].filter(Boolean).join(' ')||'Not returned')+' [REGISTRY-1]',
    '- Register court: '+clean(reg.register_court||'Not returned')+' [REGISTRY-1]',
    '- Registered address: '+clean((c.address||{}).formatted_value||'Not returned')+' [REGISTRY-1]',
    '- Register status: '+clean(c.status||'Not returned')+' [REGISTRY-1]',
    '- Registered business purpose: '+clean(typeof c.purpose==='string'?c.purpose:JSON.stringify(c.purpose||'Not returned'))+' [REGISTRY-1]',
  ];
  const sources = evidence.sources.map((s) => '- **'+clean(s.id)+' — '+clean(s.title)+'** — <'+s.url+'>; retrieved '+clean(s.retrieved_at)+
    (s.published_at?'; published '+clean(s.published_at):'; publication date not reported')+'; '+clean(s.source_type||'registry')+
    ', confidence: '+clean(s.confidence||'not rated')+(s.confidence_note?' ('+clean(s.confidence_note)+')':'')+'.');
  const section = (title, lines, empty) => ['', '## '+title, '', ...(lines.length?lines:[empty])];
  const content = [
    '# Corporate Research Briefing — '+clean(c.name),
    ...section('Executive Summary',report.executive_summary.map(citedClaim),'No evidence-backed summary claims were returned.'),
    ...section('Company Profile',profile,'No registry profile was returned.'),
    ...section('Business Model and Market Position',report.business_model_analysis.map(citedClaim),'Available evidence does not support a detailed business-model assessment.'),
    ...section('Public Findings and Developments',report.public_findings.map((x)=>bullet(x.finding+' Significance: '+x.significance,[x.source_id])),'No reliable public findings were available from this search.'),
    ...section('Analytical Observations',report.analytical_observations.map((x)=>bullet(x.observation+' Why it matters: '+x.why_it_matters+' (confidence: '+x.confidence+')',x.evidence_source_ids)),'The available evidence is too limited for a supported analytical observation.'),
    ...section('Information Gaps',report.information_gaps.map((x)=>bullet(x.gap+' Why it matters: '+x.why_it_matters)),'No specific information gaps were returned.'),
    ...section('Recommended Research Actions',report.recommended_actions.map((x)=>bullet(x.action+' Addresses: '+x.addresses_gap)),'No follow-up action is recommended from the available evidence.'),
    '', '## Sources and Limitations', '', ...sources,
    '', 'Public web material is an unverified discovery lead. Registry data is provider-reported. Citation identifiers and source types are validated automatically; semantic support of each sentence is not mechanically proven and requires professional review. Search coverage is limited; absence of a result does not establish absence of a fact or event. This briefing is not a legal opinion, audit, sanctions clearance, or solvency assessment.',
    '', '## Run Metadata', '', 'n8n execution: #'+String(run.execution_id)+'; model: '+String(run.model||'gpt-4o-mini')+'; OpenAI response: completed; source-ID validation: passed.', '',
  ];
  return content.join('\n');
}

const raw=$input.first().json.body||$input.first().json;
const fail=(code,field)=>({json:{ok:false,n8n_execution_id:String($execution.id),entrypoint:$('Normalize Input').first().json.entrypoint,failed_step:'Source and claim validation',error_code:code,failed_field:field||null,openai_status:raw.status||'unknown',model:raw.model||'gpt-4o-mini',usage:raw.usage||null,message:'No report was accepted or saved.'}});
if(raw.status!=='completed') return [fail('openai_response_not_completed','response.status')];
const item=(raw.output||[]).flatMap(x=>x.content||[]).find(x=>x.type==='output_text');
if(!item?.text) return [fail('openai_structured_output_missing','response.output_text')];
let report;try{report=JSON.parse(item.text);}catch{return [fail('openai_json_invalid','response.output_text')];}
const evidence=$('Assemble Evidence').first().json;
const sources=Object.fromEntries(evidence.sources.map(s=>[s.id,s]));
const groups=['business_activity_source_ids','public_research_source_ids','development_source_ids'];
for(const group of groups){if(!Array.isArray(report[group])||report[group].length>5)return [fail('source_selection_invalid',group)];if(report[group].some(id=>typeof id!=='string'||!sources[id]))return [fail('unknown_source_id',group)];if(group!=='business_activity_source_ids'&&report[group].some(id=>sources[id].kind!=='web_lead'))return [fail('source_type_mismatch',group)];report[group]=[...new Set(report[group])];}
for(const field of ['executive_summary','business_model_analysis','public_findings','analytical_observations','information_gaps','recommended_actions'])if(!Array.isArray(report[field])||report[field].length>(field==='analytical_observations'||field==='recommended_actions'?3:8))return [fail('report_section_invalid',field)];
const cited=(items,path)=>{if(!Array.isArray(items))return path;for(let i=0;i<items.length;i++){const ids=items[i].source_ids||items[i].evidence_source_ids;if(!Array.isArray(ids)||!ids.length||ids.some(id=>typeof id!=='string'||!sources[id]))return path+'['+i+'].source_ids';}return null;};
for(const field of ['executive_summary','business_model_analysis','analytical_observations']){const issue=cited(report[field],'$.');if(issue)return [fail('claim_source_validation_failed',field+issue)];}
if(!Array.isArray(report.public_findings))return [fail('report_section_invalid','public_findings')];
const badPublicFinding=report.public_findings.findIndex(x=>!sources[x.source_id]||sources[x.source_id].kind!=='web_lead');
if(badPublicFinding>=0)return [fail('public_finding_source_invalid','public_findings['+badPublicFinding+'].source_id')];
for(const [i,x] of report.public_findings.entries())if(typeof x.finding!=='string'||!x.finding.trim()||typeof x.significance!=='string'||!x.significance.trim())return [fail('public_finding_invalid','public_findings['+i+']')];
for(const [i,x] of report.information_gaps.entries())if(!x.gap?.trim()||!x.why_it_matters?.trim())return [fail('information_gap_invalid','information_gaps['+i+']')];
for(const [i,x] of report.recommended_actions.entries())if(!x.action?.trim()||!x.addresses_gap?.trim())return [fail('recommended_action_invalid','recommended_actions['+i+']')];
for(const field of ['uncertainties','follow_ups'])if(!Array.isArray(report[field])||report[field].length>8||report[field].some(q=>typeof q!=='string'||q.trim().length<8||q.length>240))return [fail('review_item_invalid',field)];
const c=evidence.company;
const claimCount=report.executive_summary.length+report.business_model_analysis.length+report.analytical_observations.length+report.public_findings.length;
const markdown=renderCorporateReport(report,evidence,{execution_id:$execution.id,model:raw.model||'gpt-4o-mini'});
return [{json:{ok:true,n8n_execution_id:String($execution.id),entrypoint: $('Normalize Input').first().json.entrypoint,model:raw.model||'gpt-4o-mini',openai_status:raw.status,usage:raw.usage||null,company:c,rag_context:evidence.rag_context,sources:evidence.sources,report_markdown:markdown,validation:{source_ids_valid:true,cited_claims_have_source_ids:true,validated_cited_claim_count:claimCount,semantic_entailment:'not_automatically_verified'},retrieval:{tavily_results:evidence.tavily_result_count,tavily_http_status:evidence.tavily_http_status,tavily_accepted_count:evidence.tavily_accepted_count,tavily_rejected_reasons:evidence.tavily_rejected_reasons,search_query:evidence.search_query}}}];

options.customCss:
:root {
  --font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-size-body: 14px;
  --font-size-label: 13px;
  --font-size-input: 16px;
  --font-size-header: clamp(42px, 8vw, 64px);
  --font-size-paragraph: 15px;
  --font-size-link: 12px;
  --font-size-error: 13px;
  --color-background: #070a18;
  --color-test-notice-text: #f6d28a;
  --color-test-notice-bg: rgba(34, 28, 64, 0.86);
  --color-test-notice-border: rgba(246, 210, 138, 0.3);
  --color-card-bg: rgba(15, 22, 46, 0.82);
  --color-card-border: rgba(165, 180, 255, 0.18);
  --color-card-shadow: rgba(24, 39, 104, 0.44);
  --color-link: #aebbe0;
  --color-header: #f7f8ff;
  --color-label: #dfe6ff;
  --color-input-border: rgba(157, 174, 226, 0.25);
  --color-input-text: #f5f7ff;
  --color-input-bg: rgba(7, 12, 29, 0.76);
  --color-focus-border: #9b83ff;
  --color-submit-btn-bg: #675cff;
  --color-submit-btn-text: #ffffff;
  --color-error: #ff9cad;
  --color-required: #a99aff;
  --color-clear-button-bg: #8995b7;
  --color-html-text: #dfe6ff;
  --color-html-link: #9e9aff;
  --border-radius-card: 24px;
  --border-radius-input: 14px;
  --padding-container-top: 0px;
  --padding-card: 38px;
  --padding-form-input: 16px;
  --container-width: 560px;
  --submit-btn-height: 58px;
  --box-shadow-card: 0 26px 90px rgba(1, 4, 18, 0.55);
  --opacity-placeholder: 0.58;
}

html,
body {
  min-height: 100%;
  max-width: 100%;
  overflow-x: hidden;
}

body {
  min-height: 100vh;
  color: #f5f7ff;
  background:
    radial-gradient(ellipse at 12% 8%, rgba(105, 73, 255, 0.28), transparent 38%),
    radial-gradient(ellipse at 88% 20%, rgba(39, 111, 255, 0.23), transparent 34%),
    radial-gradient(ellipse at 55% 100%, rgba(51, 62, 155, 0.17), transparent 42%),
    linear-gradient(145deg, #060816 0%, #0b1027 52%, #080d1e 100%);
  background-attachment: fixed;
}

.container {
  width: min(94vw, 560px);
  padding: clamp(28px, 8vh, 76px) 0;
}

.card,
#submitted-form {
  color: #f5f7ff;
  background: linear-gradient(145deg, rgba(20, 29, 59, 0.88), rgba(11, 17, 38, 0.88));
  border: 1px solid rgba(164, 180, 255, 0.2);
  border-radius: 24px;
  box-shadow: 0 26px 90px rgba(1, 4, 18, 0.55), 0 0 44px rgba(91, 87, 255, 0.1);
  -webkit-backdrop-filter: blur(22px);
  backdrop-filter: blur(22px);
}

.form-header {
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.form-header h1 {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  margin-inline: auto;
  overflow: visible;
  overflow-wrap: anywhere;
  white-space: normal;
  text-align: center;
  font-size: clamp(1.5rem, 7vw, 3rem);
  font-weight: 750;
  letter-spacing: 0.035em;
  line-height: 1.08;
  padding-left: 0;
  color: #c8c5ff;
  background: linear-gradient(100deg, #f7f8ff 4%, #bcb3ff 48%, #83b7ff 100%);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.form-header p {
  max-width: 34em;
  margin: 0 auto;
  color: #b8c4e7;
  font-size: 15px;
  line-height: 1.75;
}

.inputs-wrapper {
  padding-top: 34px;
  padding-bottom: 28px;
}

form label {
  color: #dfe6ff;
  font-size: 12px;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

form .form-input {
  min-height: 56px;
  border: 1px solid rgba(157, 174, 226, 0.25);
  border-radius: 14px;
  color: #f5f7ff;
  background: rgba(7, 12, 29, 0.76);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
  transition: border-color 180ms ease, box-shadow 180ms ease, background-color 180ms ease;
}

form .form-input:focus,
form .form-input:focus-visible {
  border-color: #9b83ff;
  outline: 3px solid rgba(133, 111, 255, 0.2);
  outline-offset: 1px;
  background: rgba(9, 15, 35, 0.96);
  box-shadow: 0 0 0 1px rgba(133, 111, 255, 0.3), 0 0 28px rgba(106, 87, 255, 0.18);
}

form .form-input::placeholder {
  color: #8592b5;
}

#submit-btn {
  min-height: 58px;
  border: 1px solid rgba(210, 211, 255, 0.18);
  border-radius: 15px;
  color: #ffffff;
  background: linear-gradient(105deg, #7658f6 0%, #5268f4 52%, #347fe9 100%);
  box-shadow: 0 12px 28px rgba(62, 77, 209, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.025em;
  transition: transform 180ms ease, box-shadow 180ms ease, filter 180ms ease;
}

#submit-btn:hover:not(:disabled) {
  opacity: 1;
  filter: brightness(1.08);
  transform: translateY(-1px);
  box-shadow: 0 16px 34px rgba(62, 77, 209, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.24);
}

#submit-btn:focus-visible {
  outline: 3px solid rgba(164, 147, 255, 0.55);
  outline-offset: 3px;
}

#submit-btn:disabled {
  filter: saturate(0.55);
}

#submit-hint {
  color: #9cadd4;
  line-height: 1.6;
}

#submitted-form .form-header h1 {
  font-size: clamp(1.35rem, 5.5vw, 2.25rem);
  letter-spacing: 0.04em;
  padding-left: 0;
}

#submitted-content {
  color: #d5def9;
  font-size: 15px;
  line-height: 1.75;
  overflow-wrap: anywhere;
}

.error-show,
#submit-error.error-show {
  color: #ff9cad;
}

@media only screen and (max-width: 600px) {
  .container {
    width: 100%;
    min-height: 100vh;
    padding: 24px 16px;
  }

  .card,
  #submitted-form {
    margin-bottom: 0;
    padding: 26px 21px;
    border: 1px solid rgba(164, 180, 255, 0.2);
    border-radius: 21px;
  }

  .form-header h1 {
    font-size: clamp(1.5rem, 8vw, 2.4rem);
    letter-spacing: 0.025em;
  }

  .inputs-wrapper {
    padding-top: 28px;
    padding-bottom: 22px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}
